// Golden master of the Orders HTTP API as it behaves today. Contract: test/contract/orders-api.openapi.yaml
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double for the pricing downstream (priceOf(sku) -> euros).
const prices = { apple: 10, pear: 25, gold: 100, cheap: 0.1, third: 33.33 }
const pricing = { async priceOf(sku) { return prices[sku] } }

let server
let base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, '127.0.0.1', r))
  base = `http://127.0.0.1:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw = false) =>
  fetch(`${base}/orders`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ? body : JSON.stringify(body) })
const json = async (res) => ({ status: res.status, type: res.headers.get('content-type'), body: await res.json() })

test('POST /orders creates an order: 201, json, string id, items echoed, total computed', async () => {
  const r = await json(await post({ items: [{ sku: 'apple', qty: 2 }], note: 'ignored' }))
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(Object.keys(r.body), ['id', 'items', 'total'])
  assert.equal(typeof r.body.id, 'string')
  assert.deepEqual(r.body.items, [{ sku: 'apple', qty: 2 }])
  assert.equal(r.body.total, 20)
})

test('POST /orders ids are sequential strings starting at "1" per process', async () => {
  const a = await json(await post({ items: [{ sku: 'apple', qty: 1 }] }))
  const b = await json(await post({ items: [{ sku: 'apple', qty: 1 }] }))
  assert.equal(Number(b.body.id), Number(a.body.id) + 1)
})

test('POST /orders sums several lines', async () => {
  const r = await json(await post({ items: [{ sku: 'apple', qty: 1 }, { sku: 'pear', qty: 2 }] }))
  assert.equal(r.body.total, 60)
})

test('POST /orders: total of exactly 100 gets no discount', async () => {
  const r = await json(await post({ items: [{ sku: 'gold', qty: 1 }] }))
  assert.equal(r.body.total, 100)
})

test('POST /orders: total above 100 gets 10% off', async () => {
  const r = await json(await post({ items: [{ sku: 'gold', qty: 2 }] }))
  assert.equal(r.body.total, 180)
})

test('POST /orders: total is floored to whole euros (cents are dropped)', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — fractional euros are truncated, not rounded
  const r = await json(await post({ items: [{ sku: 'third', qty: 1 }] }))
  assert.equal(r.body.total, 33)
  const d = await json(await post({ items: [{ sku: 'cheap', qty: 9 }] }))
  assert.equal(d.body.total, 0)
})

test('POST /orders: discount applies before flooring', async () => {
  // 101 * 0.9 = 90.9 -> 90
  const r = await json(await post({ items: [{ sku: 'apple', qty: 10 }, { sku: 'cheap', qty: 10 }] }))
  assert.equal(r.body.total, 90)
})

test('POST /orders: missing qty yields a null total but still 201', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — price*undefined is NaN, serialised as null
  const r = await json(await post({ items: [{ sku: 'apple' }] }))
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

test('POST /orders: unknown sku yields a null total but still 201', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — pricing double returns undefined, NaN -> null
  const r = await json(await post({ items: [{ sku: 'nope', qty: 1 }] }))
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

for (const [name, body, raw] of [
  ['no body', '', true],
  ['empty object', {}],
  ['empty items', { items: [] }],
  ['items not an array', { items: 'apple' }],
  ['malformed JSON', '{oops', true],
  ['JSON null', 'null', true],
]) {
  test(`POST /orders 400 for ${name}`, async () => {
    const r = await json(await post(body, raw))
    assert.deepEqual(r, { status: 400, type: 'application/json', body: { error: 'items required' } })
  })
}

test('POST /orders: a rejected order is not stored and consumes no id', async () => {
  const a = await json(await post({ items: [{ sku: 'apple', qty: 1 }] }))
  await post({ items: [] })
  const b = await json(await post({ items: [{ sku: 'apple', qty: 1 }] }))
  assert.equal(Number(b.body.id), Number(a.body.id) + 1)
})

test('GET /orders/{id} returns the stored order', async () => {
  const c = await json(await post({ items: [{ sku: 'pear', qty: 1 }] }))
  const r = await json(await fetch(`${base}/orders/${c.body.id}`))
  assert.equal(r.status, 200)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, c.body)
})

test('GET /orders/{id} ignores the query string', async () => {
  const c = await json(await post({ items: [{ sku: 'pear', qty: 1 }] }))
  const r = await json(await fetch(`${base}/orders/${c.body.id}?x=1`))
  assert.deepEqual(r.body, c.body)
})

test('GET /orders/{id} for an unknown id is 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404
  const r = await json(await fetch(`${base}/orders/99999`))
  assert.deepEqual(r, { status: 200, type: 'application/json', body: { error: 'not found' } })
})

for (const [method, path] of [
  ['GET', '/orders'],
  ['GET', '/orders/'],
  ['GET', '/orders/1/extra'],
  ['GET', '/'],
  ['GET', '/health'],
  ['PUT', '/orders'],
  ['DELETE', '/orders/1'],
  ['POST', '/orders/1'],
]) {
  test(`${method} ${path} -> 404 no route`, async () => {
    const r = await json(await fetch(`${base}${path}`, { method }))
    assert.deepEqual(r, { status: 404, type: 'application/json', body: { error: 'no route' } })
  })
}
EOF
